parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            0x0800 : parse_ipv4;
            0x0806 : parse_arp;
            default : accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            17 : parse_udp;
            default : accept;
        }
    }

    state parse_udp {
        packet.extract(hdr.myTunnel);
        transition accept;
    }

    state parse_arp {
        packet.extract(hdr.arp);
        transition accept;
    }
}

control MyVerifyChecksum(inout headers hdr,
                         inout metadata meta) {
    apply { }
}

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    action drop() {
        mark_to_drop(standard_metadata);
    }

    action set_nhop(macAddr_t nexthop_mac, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = nexthop_mac;
    }

    action ipv4_forward(macAddr_t nexthop_mac, egressSpec_t port) {
        set_nhop(nexthop_mac, port);
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    action arp_reply() {
        hdr.arp.sha = hdr.ethernet.srcAddr;
        hdr.arp.spa = hdr.ipv4.srcAddr;
        hdr.arp.tha = hdr.ethernet.dstAddr;
        hdr.arp.tpa = hdr.ipv4.dstAddr;
        hdr.arp.htype = 1;
        hdr.arp.ptype = 0x0800;
        hdr.arp.hlen = 6;
        hdr.arp.plen = 4;
        hdr.arp.oper = 2;
    }

    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr : lpm;
        }
        actions = {
            ipv4_forward;
            drop;
        }
        size = 1024;
        default_action = drop();
    }

    table arp_lookup {
        key = {
            hdr.arp.tpa : exact;
        }
        actions = {
            arp_reply;
            drop;
        }
        size = 1024;
        default_action = drop();
    }

    apply {
        if (hdr.ipv4.isValid()) {
            ipv4_lpm.apply();
        } else if (hdr.arp.isValid()) {
            arp_lookup.apply();
        } else {
            drop();
        }
    }
}

