        key = {
            hdr.idp.dst_id: exact;
        }
        actions = {
            idp_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    apply {
        if (hdr.ipv6.isValid()) {
            ipv6_exact.apply();
        } else if (hdr.idp.isValid()) {
            idp_exact.apply();
        }
    }
