typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header myTunnel_t {
    bit<16> proto_id;
    bit<16> dst_id;
}

struct metadata {
}

struct headers {
    ethernet_t   ethernet;
    myTunnel_t   myTunnel;
}

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_MYTUNNEL: parse_myTunnel;
            default: accept;
        }
    }

    state parse_myTunnel {
        packet.extract(hdr.myTunnel);
        transition accept;
    }

}

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    action drop() {
        mark_to_drop(standard_metadata);
    }

    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.myTunnel.proto_id = 0;
        hdr.myTunnel.dst_id = 0;
    }

    table ipv4_lpm {
        key = {
            hdr.myTunnel.dst_id: exact;
        }
        actions = {
            ipv4_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    apply {
        if (hdr.myTunnel.isValid()) {
            ipv4_lpm.apply();
        }
    }
}

control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply {  }
}

control MyComputeChecksum(inout headers  hdr, inout metadata meta) {
     apply {
        update_checksum(
        hdr.myTunnel.isValid(),
            { hdr.myTunnel.proto_id,
              hdr.myTunnel.dst_id },
            hdr.myTunnel.proto_id,
            HashAlgorithm.csum16);
    }
}

control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.myTunnel);
    }
}

V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

#include <core.p4>
#include <v1model.p4>

const bit<16> TYPE_GRE = 0x88BE;
const bit<16> TYPE_IPV4 = 0x800;
const bit<16> TYPE_ARP = 0x806;
const bit<16> TYPE_MYTUNNEL = 0x1234;

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header gre_t {
    bit<16> ver;
    bit<16> prot;
    bit<16> reserved;
    bit<16> len;
    bit<32> checksum;
    bit<32> key;
    bit<32> seq;
    bit<32> ack;
    bit<32> res;
    bit<32> offset;
    bit<32> id;
    bit<32> df;
    bit<32> mf;
    bit<32> off;
    bit<32> ttl;
    bit<32> protocol;
    bit<32> saddr;
    bit<32> daddr;
    bit<32> payload;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

header arp_t {
    bit<16> hwtype;
    bit<16> protype;
    bit<8>  hwlen;
    bit<8>  prlen;
    bit<16> opcode;
    macAddr_t srcHwAddr;
    ip4Addr_t srcProAddr;
    macAddr_t dstHwAddr;
    ip4Addr_t dstProAddr;
}

header myTunnel_t {
    bit<16> proto_id;
    bit<16> dst_id;
}

struct metadata {
}

struct headers {
    ethernet_t   ethernet;
    gre_t        gre;
    ipv4_t       ipv4;
    arp_t        arp;
    myTunnel_t   myTunnel;
}

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            TYPE_ARP: parse_arp;
            TYPE_MYTUNNEL: parse_mytunnel;
            TYPE_GRE: parse_gre;
            default: accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition accept;
    }

    state parse_arp {
        packet.extract(hdr.arp);
        transition accept;
    }

    state parse_gre {
        packet.extract(hdr.gre);
        transition accept;
    }

    state parse_mytunnel {
        packet.extract(hdr.myTunnel);
        transition accept;
    }
}

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    action drop() {
        mark_to_drop(standard_metadata);
    }

    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    action learn_mac(macAddr_t dstAddr, egressSpec_t port) {
        meta.mac_learning[dstAddr] = port;
    }

    action forward_and_learn(macAddr_t dstAddr, egressSpec_t port) {
        learn_mac(dstAddr, port);
        ipv4_forward(dstAddr, port);
    }

    action nat_ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    action nat_learn_mac(macAddr_t dstAddr, egressSpec_t port) {
        meta.nat_mac_learning[dstAddr] = port;
    }

    action nat_forward_and_learn(macAddr_t dstAddr, egressSpec_t port) {
        nat_learn_mac(dstAddr, port);
        nat_ipv4_forward(dstAddr, port);
    }

    action nat_decapsulate() {
        hdr.gre.payload = hdr.ipv4.totalLen;
        hdr.ipv4.isValid() = false;
        hdr.arp.isValid() = false;
    }

    action nat_encapsulate() {
        hdr.ipv4.isValid() = true;
        hdr.ipv4.totalLen = hdr.gre.payload;
        hdr.ipv4.hdrChecksum = 0;
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }

    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            ipv4_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    table nat_ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            nat_ipv4_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    table nat_arp_lookup {
        key = {
            hdr.arp.dstHwAddr: exact;
        }
        actions = {
            nat_forward_and_learn;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    table nat_ipv4_lookup {
        key = {
            hdr.ipv4.dstAddr: exact;
        }
        actions = {
            nat_forward_and_learn;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    table nat_gre_lookup {
        key = {
            hdr.gre.key: exact;
        }
        actions = {
            nat_decapsulate;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    apply {
        if (hdr.ipv4.isValid()) {
            ipv4_lpm.apply();
        } else if (hdr.arp.isValid()) {
            nat_arp_lookup.apply();
        } else if (hdr.gre.isValid()) {
            nat_gre_lookup.apply();
        } else if (hdr.myTunnel.isValid()) {
            nat_ipv4_lookup.apply();
        }
    }
}

control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply {  }
}

control MyComputeChecksum(inout headers  hdr, inout metadata meta) {
     apply {
        update_checksum(
        hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }
}

control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.arp);
        packet.emit(hdr.gre);
        packet.emit(hdr.myTunnel);
    }
}

V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

