const bit<16> TYPE_IPV6 = 0x86DD;
const bit<16> TYPE_SRH = 0x894F;

#define MAX_HOPS 8

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<128> ip6Addr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header sr_nh_t {
    bit<7> nh;
}

header sr_seg_t {
    bit<1> srh_flag;
    bit<15> seg_len;
}

