    bit<4>     version;
    bit<4>     trafficClass;
    bit<8>     flowLabel;
    bit<16>    payloadLength;
    bit<8>     nextHeader;
    bit<8>     hopLimit;
    ip6Addr_t srcAddr;
    ip6Addr_t dstAddr;
}

header sr_nh_list_t {
    sr_nh_t [MAX_HOPS] sr_nh_list;
}

header sr_seg_list_t {
    sr_seg_t [MAX_HOPS] sr_seg_list;
}

struct metadata {
}

struct headers {
    ethernet_t           ethernet;
    sr_nh_list_t         sr_nh_list;
    sr_seg_list_t        sr_seg_list;
    ipv6_t               ipv6;
}

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_SRH: parse_srh;
            default: accept;
        }
    }

    state parse_srh {
        packet.extract(hdr.sr_nh_list.next);
        transition select(hdr.sr_nh_list.last.srh_flag) {
            1: parse_ipv6;
            default: parse_srh;
        }
    }

    state parse_ipv6 {
        packet.extract(hdr.ipv6);
        transition accept;
    }

}

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    action drop() {
        mark_to_drop(standard_metadata);
    }

    action srcRoute_nhop() {
        standard_metadata.egress_spec = (bit<9>)hdr.sr_nh_list[0].nh;
        hdr.sr_nh_list.pop_front(1);
    }

    action srcRoute_finish() {
        hdr.ethernet.etherType = TYPE_IPV6;
    }

    action update_ttl(){
        hdr.ipv6.hopLimit = hdr.ipv6.hopLimit - 1;
    }

    apply {
        if (hdr.sr_nh_list[0].isValid()){
            if (hdr.sr_nh_list[0].srh_flag == 1){
                srcRoute_finish();
            }
            srcRoute_nhop();
            if (hdr.ipv6.isValid()){
                update_ttl();
            }
        }else{
            drop();
        }
    }
}

