#include <core.p4>
#include <v1model.p4>

const bit<16> TYPE_MYTUNNEL = 0x1234;

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header myTunnel_t {
    bit<16> proto_id;
    bit<16> dst_id;
}

header myHeader_t{
	bit<16> id;
	bit<16> len;
}

struct metadata {
}

struct headers {
    ethernet_t   ethernet;
    myTunnel_t   myTunnel;
	myHeader_t myHeader;
}

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_MYTUNNEL: parse_myTunnel;
            default: accept;
        }
    }

    state parse_myTunnel {
        packet.extract(hdr.myTunnel);
        transition parse_myHeader;
    }

	state parse_myHeader {
		packet.extract(hdr.myHeader);
		transition accept;
	}
}

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {
    action drop() {
        mark_to_drop(standard_metadata);
    }

    action clone_packet(){
		standard_metadata.clone_session = 1;
	}

    action ipv4_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.myTunnel.proto_id = hdr.myTunnel.proto_id + 1;
        hdr.myTunnel.dst_id = hdr.myTunnel.dst_id + 1;
        hdr.myHeader.len = hdr.myHeader.len + 1;
        hdr.myHeader.id = hdr.myHeader.id + 1;
    }

    table ipv4_lpm {
        key = {
            hdr.myTunnel.proto_id: exact;
			hdr.myTunnel.dst_id: exact;
            hdr.myHeader.len: exact;
			hdr.myHeader.id: exact;
        }
        actions = {
            ipv4_forward;
            drop;
            clone_packet;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    apply {
        if (hdr.myTunnel.isValid()) {
            ipv4_lpm.apply();
        }
    }
}

control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply {  }
}

control MyComputeChecksum(inout headers  hdr, inout metadata meta) {
     apply {
        update_checksum(
        hdr.myTunnel.isValid(),
            { hdr.myTunnel.proto_id,
              hdr.myTunnel.dst_id,
			  hdr.myHeader.len,
			  hdr.myHeader.id},
            hdr.myTunnel.proto_id,
            HashAlgorithm.csum16);
    }
}

control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.myTunnel);
		packet.emit(hdr.myHeader);
    }
}

V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

