    bit<16> proto_id;
    bit<16> dst_id;
}

struct headers {
    ethernet_t   ethernet;
    ipv4_t       ipv4;
    udp_t        udp;
    mcast_t      mcast;
    myTunnel_t   myTunnel;
}

struct metadata {
    bit<4>         isMcast;
    bit<32>        mcastGroup;
    bit<32>        mcastSource;
    bit<32>        mcastReserved;
    bit<48>        tunnelDstId;
    bit<48>        tunnelSrcId;
    bit<16>        tunnelProtoId;
    bit<16>        tunnelDscp;
    bit<16>        tunnelEcn;
    bit<16>        tunnelTotalLen;
    bit<16>        tunnelIdentification;
    bit<3>         tunnelFlags;
    bit<13>        tunnelFragOffset;
    bit<8>         tunnelTtl;
    bit<8>         tunnelProtocol;
    bit<16>        tunnelHdrChecksum;
    bit<16>        tunnelPayloadLength;
    bit<16>        tunnelChksum;
    bit<32>        tunnelIpv4SrcAddr;
    bit<32>        tunnelIpv4DstAddr;
    bit<32>        tunnelUdpSrcPort;
    bit<32>        tunnelUdpDstPort;
    bit<32>        tunnelUdpLength;
    bit<32>        tunnelUdpChksum;
