parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t standard_metadata) {

    state start {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            0x0800 : parse_ipv4;
            default : accept;
        }
    }

    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition select(hdr.ipv4.protocol) {
            17 : parse_udp;
            default : accept;
        }
    }

    state parse_udp {
        packet.extract(hdr.udp);
        transition select(hdr.udp.length) {
            size_of(hdr.udp) : parse_mcast;
            default          : accept;
        }
    }

    state parse_mcast {
        packet.extract(hdr.mcast);
        transition accept;
    }
}

control MyVerifyChecksum(inout headers hdr,
                         inout metadata meta) {
    apply {
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);

        update_checksum(
            hdr.udp.isValid(),
            { hdr.udp.srcPort,
              hdr.udp.dstPort,
              hdr.udp.length,
              hdr.udp.chksum },
            hdr.udp.chksum,
            HashAlgorithm.csum16);
    }
}

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t standard_metadata) {

    action drop() {
        mark_to_drop(standard_metadata);
    }

    action set_tunnel_headers(bit<16> proto_id, bit<16> dst_id) {
        hdr.myTunnel.proto_id = proto_id;
        hdr.myTunnel.dst_id = dst_id;
    }

    action forward(egressSpec_t port) {
        standard_metadata.egress_spec = port;
    }

    action decr_ttl() {
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    action increment_ttl() {
        hdr.ipv4.ttl = hdr.ipv4.ttl + 1;
    }

    action verify_ttl() {
        if (hdr.ipv4.ttl == 0) {
            drop();
        }
    }

    action update_checksum_ipv4() {
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);
    }

    action update_checksum_udp() {
        update_checksum(
            hdr.udp.isValid(),
            { hdr.udp.srcPort,
              hdr.udp.dstPort,
              hdr.udp.length,
              hdr.udp.chksum },
            hdr.udp.chksum,
            HashAlgorithm.csum16);
    }

    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr : lpm;
        }
        actions = {
            forward;
            drop;
        }
        const default_action = drop();
    }

    table mcast_lookup {
        key = {
            hdr.mcast.groupAddress : exact;
        }
        actions = {
            forward;
            drop;
        }
        const default_action = drop();
    }

    apply {
        verify_ttl();
        increment_ttl();
        update_checksum_ipv4();
        update_checksum_udp();

        if (meta.isMcast == 1) {
            mcast_lookup.apply();
        } else {
            ipv4_lpm.apply();
        }

        if (hdr.myTunnel.isValid()) {
            set_tunnel_headers(hdr.myTunnel.proto_id, hdr.myTunnel.dst_id);
        }
    }
}

control MyEgress(inout headers hdr,
                 inout metadata meta,
                 inout standard_metadata_t standard_metadata) {
    apply {
        decrement_ttl();
        update_checksum_ipv4();
        update_checksum_udp();
    }
}

control MyComputeChecksum(inout headers hdr, inout metadata meta) {
    apply {
        update_checksum(
            hdr.ipv4.isValid(),
            { hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);

        update_checksum(
            hdr.udp.isValid(),
            { hdr.udp.srcPort,
              hdr.udp.dstPort,
              hdr.udp.length,
              hdr.udp.chksum },
            hdr.udp.chksum,
            HashAlgorithm.csum16);
    }
}

control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.udp);
        packet.emit(hdr.mcast);
        packet.emit(hdr.myTunnel);
    }
}

V1Switch(
MyParser(),
MyVerifyChecksum(),
MyIngress(),
MyEgress(),
MyComputeChecksum(),
MyDeparser()
) main;

